def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for y in range(3 * h):
        by, iy = divmod(y, h)
        sy = h - 1 - iy if by % 2 == 0 else iy
        row = []
        for bx in range(2):
            for x in range(w):
                sx = w - 1 - x if bx == 0 else x
                row.append(grid[sy][sx])
        out.append(row)
    return out
